/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormControlEventHandler(formControlStr(CustParameters, AVASumUpdateStandardPacking), FormControlEventType::Modified)]
public static void AVASumUpdateStandardPacking_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormRun                     formRun = sender.formRun();
    FormDataSource              salesParametersDS = formRun.dataSource(formDataSourceStr(CustParameters,SalesParameters));
    SalesParameters             salesParameters;
    FormComboBoxControl         sumUpdStandardPacking  = sender as FormComboBoxControl;
    SalesPurchSummarySumByCtrl  sumByCtrl1 = formRun.parmsumByCtrl();
    if (salesParametersDS)
    {

        salesParameters = salesParametersDS.cursor();
        salesParameters.AVASumByPacking =  sumByCtrl1.selection2Index(sumUpdStandardPacking.selection());
    }
}
